HELP = {'': 'Usage: tool [options] <command>\n\nManage named remotes.\n\nCommands:\n  remote  Inspect and update remotes.\n\nOptions:\n  -h, --help         Show this help and exit\n  --verbose, -v, /V  Increase verbosity [default: 0] (repeatable) (also applies to subcommands)\n', 'remote': 'Usage: tool remote [options] <command>\n\nInspect and update remotes.\n\nCommands:\n  add   Show how a remote would be added.\n  list  Show example remotes.\n\nOptions:\n  -h, --help                 Show this help and exit\n  --verbose, -v, /V          Increase verbosity [default: 0] (repeatable) (also applies to subcommands)\n  --token, -t, /Token TOKEN  Authentication token (also applies to subcommands)\n', 'remote add': 'Usage: tool remote add [options] <NAME>\n\nShow how a remote would be added.\n\nArguments:\n  NAME  Remote name\n\nOptions:\n  -h, --help                   Show this help and exit\n  --verbose, -v, /V            Increase verbosity [default: 0] (repeatable)\n  --token, -t, /Token TOKEN    Authentication token\n  --url, -u, /URL, /U, /u URL  Remote URL (required)\n  --force, -f                  Allow replacing an existing remote [default: False]\n', 'remote list': 'Usage: tool remote list [options]\n\nShow example remotes.\n\nOptions:\n  -h, --help                 Show this help and exit\n  --verbose, -v, /V          Increase verbosity [default: 0] (repeatable)\n  --token, -t, /Token TOKEN  Authentication token\n'}
